<script setup>
import { computed, ref } from 'vue';
import { Link, router, useForm } from '@inertiajs/vue3';
import { Dialog, DialogPanel, DialogTitle } from '@headlessui/vue';
import { Plus, BookOpen, GripVertical, ChevronUp, ChevronDown, Pencil, Trash2, Layers, X, Inbox, CalendarClock } from 'lucide-vue-next';
import LessonTypePicker from './LessonTypePicker.vue';
import { lessonIcon, lessonTypeLabel } from './lessonTypes';
const props = defineProps({ course: Object, workspace: { type: String, default: 'admin' }, disabled: Boolean });
const moduleForm = useForm({ title: '', description: '' });
const editing = ref(null), editingTitle = ref(''), collapsed = ref({}), deletion = ref(null), pending = ref(false), error = ref('');
const modules = computed(() => props.course.modules || []);
const lessons = computed(() => modules.value.flatMap(module => module.lessons || []));
const duration = computed(() => lessons.value.reduce((sum, lesson) => sum + Number(lesson.duration_minutes || 0), 0));
const base = computed(() => `/${props.workspace}/courses/${props.course.id}`);
const moduleUrl = module => props.workspace === 'admin' ? `/admin/modules/${module.id}` : `${base.value}/modules/${module.id}`;
const lessonUrl = (module, lesson) => props.workspace === 'admin' ? `/admin/lessons/${lesson.id}` : `${moduleUrl(module)}/lessons/${lesson.id}`;
const createUrl = module => props.workspace === 'admin' ? `/admin/modules/${module.id}/lessons/create` : `${moduleUrl(module)}/lessons/create`;
const icon = lesson => lessonIcon(lesson);
const picking = ref(null);
const chooseType = type => { const module = picking.value; picking.value = null; router.visit(`${createUrl(module)}?type=${type}`); };
const dripLabel = lesson => lesson.unlock_type === 'days_after_enrollment' ? `Day ${lesson.unlock_days_after_enrollment}` : lesson.unlock_type === 'date' && lesson.unlock_at ? new Date(lesson.unlock_at).toLocaleDateString(undefined, { day: 'numeric', month: 'short' }) : null;
const callbacks = () => ({ preserveScroll: true, preserveState: true, onStart: () => { pending.value = true; error.value = ''; }, onFinish: () => pending.value = false, onError: errors => error.value = Object.values(errors).flat().join(' ') });
function addModule() { moduleForm.post(`${base.value}/modules`, { ...callbacks(), onSuccess: () => moduleForm.reset() }); }
function rename(module) { router.put(moduleUrl(module), { title: editingTitle.value, description: module.description }, { ...callbacks(), onSuccess: () => editing.value = null }); }
function reorder(items, from, to, module = null) { if (props.disabled || pending.value || from === to || to < 0 || to >= items.length) return; const order = items.map(item => item.id); order.splice(to, 0, order.splice(from, 1)[0]); router.post(`/authoring/courses/${props.course.id}/reorder`, { order, module_id: module?.id }, callbacks()); }
function startDrag(event, type, index, moduleId = null) { event.dataTransfer.setData('application/jk-curriculum', JSON.stringify({ type, index, moduleId })); event.dataTransfer.effectAllowed = 'move'; }
function drop(event, type, index, module = null) { if (props.disabled || pending.value) return; try { const source = JSON.parse(event.dataTransfer.getData('application/jk-curriculum')); if (source.type === type && source.moduleId === (module?.id ?? null)) reorder(module ? module.lessons : modules.value, source.index, index, module); } catch { /* Ignore unrelated file drops. */ } }
function remove() { router.delete(deletion.value.url, { ...callbacks(), onSuccess: () => deletion.value = null }); }
</script>

<template>
    <div class="space-y-5">
        <div class="flex flex-wrap items-center justify-between gap-4 rounded-2xl bg-surface-900 p-6 text-white"><div><p class="text-[10px] font-semibold uppercase tracking-[0.2em] text-orange-300">CURRICULUM BUILDER</p><h2 class="mt-2 text-xl font-semibold">Shape the learning journey.</h2><p class="mt-2 text-xs leading-5 text-surface-400">Organize modules, build rich lessons and arrange them in the order learners will follow.</p></div><div class="flex gap-5 text-center"><div><p class="text-xl font-semibold">{{ modules.length }}</p><p class="mt-1 text-[10px] text-surface-400">MODULES</p></div><div><p class="text-xl font-semibold">{{ lessons.length }}</p><p class="mt-1 text-[10px] text-surface-400">LESSONS</p></div><div><p class="text-xl font-semibold">{{ duration }}</p><p class="mt-1 text-[10px] text-surface-400">MINUTES</p></div></div></div>
        <div v-if="error" role="alert" class="rounded-xl bg-rose-50 p-4 text-sm text-rose-800">{{ error }}</div>
        <div v-if="!modules.length" class="rounded-2xl border border-dashed border-surface-300 bg-white px-6 py-12 text-center"><BookOpen class="mx-auto h-10 w-10 text-primary-400" /><h3 class="mt-4 text-lg font-semibold">Every great course starts with a clear structure.</h3><p class="mx-auto mt-2 max-w-md text-sm leading-6 text-surface-500">Create your first module below, then add articles, PDFs, slides, videos, quizzes, assignments and case studies.</p></div>
        <section v-for="(module, moduleIndex) in modules" :key="module.id" class="overflow-hidden rounded-2xl border border-surface-200 bg-white shadow-sm" @dragover.prevent @drop.stop.prevent="drop($event, 'module', moduleIndex)">
            <div class="flex flex-wrap items-center gap-3 border-b border-surface-100 bg-surface-50 px-4 py-4 sm:px-5" :draggable="!disabled && !pending" @dragstart.stop="startDrag($event, 'module', moduleIndex)">
                <GripVertical class="hidden h-4 w-4 cursor-grab text-surface-400 sm:block" aria-hidden="true" /><span class="grid h-8 w-8 shrink-0 place-items-center rounded-lg bg-white text-xs font-bold text-primary-700 shadow-sm">{{ String(moduleIndex + 1).padStart(2, '0') }}</span>
                <div class="min-w-0 flex-1"><div v-if="editing === module.id" class="flex gap-2"><input v-model="editingTitle" aria-label="Module title" class="min-w-0 flex-1 rounded-lg border border-surface-300 px-3 py-2 text-sm" @keydown.enter.prevent="rename(module)" @keydown.esc="editing = null" /><button type="button" @click="rename(module)" :disabled="pending || !editingTitle.trim()" class="text-xs font-semibold text-primary-700">Save</button><button type="button" @click="editing = null" aria-label="Cancel rename"><X class="h-4 w-4" /></button></div><button v-else type="button" @click="collapsed[module.id] = !collapsed[module.id]" :aria-expanded="!collapsed[module.id]" class="block max-w-full truncate text-left text-sm font-semibold">{{ module.title }}</button><p class="mt-1 text-[11px] text-surface-500">{{ module.lessons?.length || 0 }} lessons · {{ module.is_published ? 'Visible module' : 'Hidden module' }}</p></div>
                <div class="flex items-center gap-1"><button type="button" :disabled="disabled || pending || moduleIndex === 0" @click="reorder(modules, moduleIndex, moduleIndex - 1)" :aria-label="`Move ${module.title} up`" class="curriculum-icon"><ChevronUp class="h-4 w-4" /></button><button type="button" :disabled="disabled || pending || moduleIndex === modules.length - 1" @click="reorder(modules, moduleIndex, moduleIndex + 1)" :aria-label="`Move ${module.title} down`" class="curriculum-icon"><ChevronDown class="h-4 w-4" /></button><button type="button" :disabled="disabled || pending" @click="editing = module.id; editingTitle = module.title" :aria-label="`Rename ${module.title}`" class="curriculum-icon"><Pencil class="h-3.5 w-3.5" /></button><button type="button" :disabled="disabled || pending" @click="deletion = { title: module.title, url: moduleUrl(module), module: true }" :aria-label="`Delete ${module.title}`" class="curriculum-icon hover:text-rose-600"><Trash2 class="h-3.5 w-3.5" /></button></div>
            </div>
            <div v-if="!collapsed[module.id]">
                <div v-for="(lesson, index) in module.lessons" :key="lesson.id" :draggable="!disabled && !pending" @dragstart.stop="startDrag($event, 'lesson', index, module.id)" @dragover.stop.prevent @drop.stop.prevent="drop($event, 'lesson', index, module)" class="flex items-center gap-3 border-b border-surface-100 px-4 py-4 hover:bg-surface-50 sm:px-5"><GripVertical class="hidden h-4 w-4 cursor-grab text-surface-300 sm:block" /><span class="grid h-9 w-9 shrink-0 place-items-center rounded-xl bg-primary-50 text-primary-600"><component :is="icon(lesson)" class="h-4 w-4" /></span><div class="min-w-0 flex-1"><Link :href="`${lessonUrl(module, lesson)}/edit`" class="block truncate text-sm font-medium text-surface-800 hover:text-primary-700">{{ lesson.title }}</Link><p class="mt-1 flex flex-wrap items-center gap-x-1 text-[11px] text-surface-400"><span>{{ lessonTypeLabel(lesson) }} · {{ lesson.duration_minutes || 0 }} min · {{ lesson.is_published ? 'Visible' : 'Hidden' }}{{ lesson.is_free_preview ? ' · Free preview' : '' }}</span><span v-if="dripLabel(lesson)" class="inline-flex items-center gap-1 rounded bg-amber-50 px-1.5 py-0.5 font-medium text-amber-800"><CalendarClock class="h-3 w-3" />{{ dripLabel(lesson) }}</span></p></div><div class="flex gap-0.5"><button type="button" :disabled="disabled || pending || index === 0" @click="reorder(module.lessons, index, index - 1, module)" :aria-label="`Move ${lesson.title} up`" class="curriculum-icon"><ChevronUp class="h-3.5 w-3.5" /></button><button type="button" :disabled="disabled || pending || index === module.lessons.length - 1" @click="reorder(module.lessons, index, index + 1, module)" :aria-label="`Move ${lesson.title} down`" class="curriculum-icon"><ChevronDown class="h-3.5 w-3.5" /></button><Link v-if="['assignment', 'case_study'].includes(lesson.content_type)" :href="`/authoring/lessons/${lesson.id}/submissions`" :aria-label="`Review submissions for ${lesson.title}`" title="Review submissions" class="curriculum-icon"><Inbox class="h-3.5 w-3.5" /></Link><Link :href="`${lessonUrl(module, lesson)}/edit`" :aria-label="`Edit ${lesson.title}`" class="curriculum-icon"><Pencil class="h-3.5 w-3.5" /></Link><button type="button" :disabled="disabled || pending" @click="deletion = { title: lesson.title, url: lessonUrl(module, lesson), module: false }" :aria-label="`Delete ${lesson.title}`" class="curriculum-icon hover:text-rose-600"><Trash2 class="h-3.5 w-3.5" /></button></div></div>
                <div v-if="!module.lessons?.length" class="px-5 py-7 text-center text-sm text-surface-400">This module is ready for its first lesson.</div><button v-if="!disabled" type="button" @click="picking = module" class="flex w-full items-center justify-center gap-2 px-5 py-3.5 text-xs font-semibold text-primary-700 hover:bg-primary-50"><Plus class="h-4 w-4" />Add a lesson, quiz or assignment</button>
            </div>
        </section>
        <form v-if="!disabled" @submit.prevent="addModule" class="rounded-2xl border-2 border-dashed border-surface-200 bg-white p-5 sm:p-6"><h3 class="mb-4 flex items-center gap-2 text-sm font-semibold"><Layers class="h-4 w-4 text-primary-600" />Add a module</h3><div class="flex flex-col gap-3 sm:flex-row"><label class="flex-1 text-xs font-medium text-surface-600">Module title<input v-model="moduleForm.title" required maxlength="255" placeholder="e.g. Foundations of project management" class="mt-2 w-full rounded-xl border border-surface-200 px-3 py-2.5 text-sm" /></label><label class="flex-1 text-xs font-medium text-surface-600">Description <span class="text-surface-400">(optional)</span><input v-model="moduleForm.description" placeholder="What does this module cover?" class="mt-2 w-full rounded-xl border border-surface-200 px-3 py-2.5 text-sm" /></label><button type="submit" :disabled="pending || moduleForm.processing" class="self-end rounded-xl bg-primary-700 px-5 py-3 text-xs font-semibold text-white disabled:opacity-40">{{ moduleForm.processing ? 'Adding…' : 'Add module' }}</button></div><p v-for="message in moduleForm.errors" :key="message" role="alert" class="mt-2 text-xs text-rose-700">{{ message }}</p></form>
        <LessonTypePicker :open="!!picking" :module-title="picking?.title" @close="picking = null" @select="chooseType" />
        <Dialog :open="!!deletion" @close="!pending && (deletion = null)" class="relative z-50"><div class="fixed inset-0 bg-surface-950/50" aria-hidden="true" /><div class="fixed inset-0 flex items-center justify-center p-5"><DialogPanel class="w-full max-w-md rounded-2xl bg-white p-6 shadow-xl"><DialogTitle class="text-lg font-semibold">Delete {{ deletion?.module ? 'module' : 'lesson' }}?</DialogTitle><p class="mt-3 text-sm leading-6 text-surface-600">“{{ deletion?.title }}” will be removed{{ deletion?.module ? ', including all its lessons' : '' }}. This cannot be undone.</p><p v-if="error" role="alert" class="mt-3 text-sm text-rose-700">{{ error }}</p><div class="mt-6 flex justify-end gap-3"><button type="button" @click="deletion = null" :disabled="pending" class="rounded-xl border border-surface-200 px-4 py-2 text-sm">Keep it</button><button type="button" @click="remove" :disabled="pending" class="rounded-xl bg-rose-600 px-4 py-2 text-sm font-semibold text-white">{{ pending ? 'Deleting…' : 'Delete permanently' }}</button></div></DialogPanel></div></Dialog>
    </div>
</template>
<style scoped>.curriculum-icon { display: inline-flex; align-items: center; justify-content: center; width: 32px; height: 36px; border-radius: 8px; color: #64748b; }.curriculum-icon:hover { background: #e2e8f0; }.curriculum-icon:disabled { opacity: .25; cursor: not-allowed; }.curriculum-icon:focus-visible { outline: 2px solid #2563eb; }</style>
